package io.github.danielalmeida19.orchestranode.database.dao;

/**
 * Interface to provide the contrat of a class to implements Data Access Object
 * pattern.</br>
 *
 * The class param {@link ID} represents the type of the unique identificator
 * in the class of the instance to search in database. The class param
 * {@link #T} represents the class of the instance
 *
 * @author Daniel
 */
public interface GenericDAO<ID, T> {

    /**
     * The method to save an instance of a generic class. This method assumes that
     * the instance is new and the id is autogenerated by the presetted DBMS
     */
    void save(T instance);

    /**
     * Method to find an instance of a generic class by a generic ID
     */
    T findById(ID id);

    /**
     * Method to delete an instance of a generic class by a generic ID
     */
    void deleteById(ID id);
}
